#!/usr/bin/env python3
"""Turn 35 Wave 97: THE SCENARIO MECHANICS, KICK-OFF IS THE MOST DANGEROUS MOMENT, AND A SUB-TIMING CONFLICT.

Wave 97's centrepieces:

1. THE LIMITED-TIME SCENARIO BLOCKS THE DAILY ONE, and there are only three attempts. That is
   the single most operationally important scenario fact the corpus lacked: a limited-time
   scenario does not sit alongside the daily one, it REPLACES it until it is finished or the
   three chances are spent. So the 50-coin daily routine is not guaranteed - it can be taken
   away by an event, and the event itself can demand four goals in 45 minutes with a half-tired
   squad of rare players.

2. KICK-OFF IS THE MOST DANGEROUS MOMENT IN A MATCH. Two independent sources say so, and both
   give the same answer: **play defensive the instant the opponent has kick-off**, and man-mark
   their target with your forward while a second finger holds the secondary press. The corpus's
   defending rules were written about open play; this is the one moment where the correct
   tactic changes before the ball is even in motion.

3. A SUB-TIMING CONFLICT. The corpus says substitutions are allowed at throw-ins and corners
   (C2). Two independent December 2024 reports say a regression BLOCKED them there - and it is
   not recorded as fixed. Opened as C-031 rather than silently preferring either claim.
"""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w97')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid

def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid

os.makedirs(RAW_DIR,exist_ok=True)

e_sc=new_ev("r/DreamLeagueSoccer 1bfgxu7 'I hate limited time scenarios with all my heart and soul' (15 Mar 2024 - the limited-time scenario blocking the daily one, the three-attempt limit, the four-goals-in-45-minutes demand, and the AI loose-ball and pass-theft observations), r/DreamLeagueSoccer 1hmyx6j 'Why are Scenarios so hard now?' (26 Dec 2024 - the easy scenarios playing at medium, and the substitution block at throw-ins and corners), r/DreamLeagueSoccer 1f4x5jj 'Impossible scenario' (2024 - the win-by-3-or-4-goals variant and the Wolves vs Chelsea 2-2 at 57 minutes example), r/DreamLeagueSoccer 18edxaw 'Way too easy' (9 Dec 2023 - the halfway-line-to-wingers scenario exploit and the weakened AI defenders), r/DreamLeagueSoccer 1er5usb 'How to NOT let DLL manipulate you' (13 Aug 2024 - kick-off as the most dangerous moment, and playing defensive on their kick-off), r/DreamLeagueSoccer 1ap2595 (12 Feb 2024 - the kick-off man-mark, the set-piece anti-turnover rules, and the cross-field lofted ball as an AI confuser), r/DreamLeagueSoccer 1tp8zg7 (27 May 2026 - the clan relegation-zone management and the OG-title/Discord recruitment), r/DreamLeagueSoccer 1peo0q2 (5 Dec 2025 - the 50-wins-and-a-screenshot recruitment condition), r/DreamLeagueSoccer 1qz14ir (8 Feb 2026 - the world-record run's DLL-only self-imposed rules), r/DreamLeagueSoccer 176ntor (13 Oct 2023 - group training 16-20 and fitness-before-technical), LevelWinner DLS2024 beginner guide (15 Mar 2024 - the division difficulty scaling), r/DreamLeagueSoccer 1d72e13 (3 Jun 2024 - the Career difficulty patch)",
    "THE SCENARIO MECHANICS, KICK-OFF AS THE MOST DANGEROUS MOMENT, AND A SUB-TIMING CONFLICT. (1) THE LIMITED-TIME SCENARIO BLOCKS THE DAILY ONE: 'they think we can score 4 goals in 45 minutes with half tired team with rare players... I tried 3 times and scoreline was 2*3, 3-3, 3-3. Your pass won't connect well your players forget to make some runs. **And the worst part you don't get normal scenario until limited time scenario is over or you use your all 3 chances.**' So the 50-coin daily routine is NOT guaranteed - it can be taken away by an event, and the event can demand four goals in 45 minutes with a half-tired rare squad. (2) THE WIN-BY-N VARIANT: 'Recently, **they added an option to some scenarios where you would have to win with a 3 or 4 goals difference**, which made it a little more challenging yet still manageable. That was until I saw an extreme difficulty one yesterday: **Wolves vs Chelsea (play as) 2-2 at 57th minute. You have to win by a 4 goals difference.**' So a scenario can require four goals in the last 33 minutes. (3) THE AI OBSERVATIONS IN SCENARIOS: 'Capable to do 3 sliding tackles in less than 1.5 second, the 3rd player will come pickup the loose ball. Not just Strength Tackling above 90. **My AI is boosted with flash buff. Say looseball is 2 meter away from my player. AI can pickup ball despite being much further 5 meter away. Any pass above 40% power no matter how accurate, will get stolen.**' So keep scenario passes under 40% power, and expect the AI to collect loose balls from further away than physics allows. (4) THE SCENARIO EXPLOIT, from the other direction: 'i noticed scenarios are also way too easy in dls23 i literally never won a scenario now i easily win the very hard ones by 3-4 goals the thing is **AI defenders seem to have turned to shit and attackers take runs more frequently** if you just **pass around the halfway line to your wingers, it opens up so much space** and you can abuse that hence you can trick top tier teams with weaker players.' So the exploitable shape is patient circulation at the halfway line to the wingers. (5) KICK-OFF IS THE MOST DANGEROUS MOMENT: 'If they are C spammers, **hold possession most of the game, and play defensive as soon as they get the ball. Also, play defensive when they have kick-off. Kick-off is the most dangerous time.** If you take the ball during kick-off and hold possession for most of the game while slowly scoring goals, there you go - you beat them.' (6) THE KICK-OFF MAN-MARK: '**during the kickoff immediately run towards the player they want to target and man mark him with your forward while you hold down on the screen with your other finger so an ai player will press whoever they kicked off to.**' So the kick-off routine is: mark their target with your striker, and secondary-press the receiver. (7) THE SET-PIECE ANTI-TURNOVER RULES: 'For set pieces, **always avoid turnovers. On goal kicks, loft pass to the defender on the opposite side of the goalie with almost full power by moving the arrow as far that direction as it can go. On free kicks, if the goalie is an option, take it. if not, do not shoot. Only legendary players can be trusted to hit that one in a million free kick goal.** Instead, pass to the closest and most open player. **On corner kicks, do not mess with the direction and kick it at 2/3 power.**' (8) THE CROSS-FIELD LOFTED BALL CONFUSES THE AI: '**Cross field lofted balls also confuse the defensive ai**' - and 'most skill moves like a rainbow are high percentage and will get you a goal', with the caveat 'any tackle will make you lose the ball, so be smart and quick with passes.' (9) A SUB-TIMING CONFLICT: the corpus's CLAIM-378 and CLAIM-1807 (both C2) say throw-ins and corners ALLOW substitutions. Two independent December 2024 reports say the opposite: '**You can't even make a substitution when the play is stopped for a throw-in, corner kick, etc.**' and CLAIM-1125 records the same regression. **Opened as C-031 rather than silently preferring either claim** - the general rule stands, but the regression is the more specific and later evidence. (10) THE CLAN RELEGATION ZONE: 'Only need 10 People I got 3 regulations... **The bottom 10 is the relegation zone. I always remove the bottom 10 but if any of them reach 100k they will never get removed. Avoid the bottom 10 at all cost to avoid potentially removed.**' So a competitive clan runs a relegation zone with a 100k safety threshold - which is the concrete form of the corpus's 'clan choice is competitive' finding. (11) THE SCREENSHOT-VERIFICATION RECRUITMENT: 'Looking for **One more person willing to get a minimum of 50 wins** within the remaining time limit (5 days). **Send a screenshot of your prize ladder** & I'll DM you the code once you've met the conditions.' So elite clans verify claims with screenshots before issuing codes. (12) THE CLAN-TAG REQUIREMENT AND DISCORD: 'the first 5 players to join will get an **OG title role on the Discord server** and a direct say in clan announcements... **Willingness to represent the clan tag [AoG] in team name**' - and 'Be a member of an active clan if you don't want to join a clan just for the sake of it... **Preferably Division 1 or higher team**.' (13) THE RECORD RUN'S SELF-IMPOSED RULES: '**No career mode matches, scenarios, dream draft, or any other game modes were allowed which could help upgrade my team and gain me gems and/or coins. I could ONLY play DLL matches and only use those rewards to upgrade my common team.**' So the 16-day record was achieved with one mode and one reward stream - which is the cleanest possible evidence that DLL alone is sufficient. (14) THE CAREER DIFFICULTY PATCH: 'The previous patch made Career mode harder by **absolutely disabling your players and turning 70 rated AI players into gods that can match upgraded gold players.**'",
    "THE LIMITED-TIME SCENARIO BLOCKS THE DAILY ONE, and there are only three attempts - so the 50-coin daily routine is not guaranteed and can be replaced by an event demanding four goals in 45 minutes with a half-tired rare squad. KICK-OFF IS THE MOST DANGEROUS MOMENT: play defensive the instant the opponent has kick-off, and man-mark their target with your forward while a second finger holds the secondary press. THE SCENARIO EXPLOIT: patient circulation around the halfway line to the wingers opens space against weakened AI defenders - and keep scenario passes under 40% power, because anything above gets stolen. THE SET-PIECE ANTI-TURNOVER RULES. A SUB-TIMING CONFLICT opened as C-031: the corpus says subs are allowed at throw-ins and corners; two independent December 2024 reports say a regression blocked them. THE CLAN RELEGATION ZONE with a 100k safety threshold, and screenshot-verified recruitment.",
    "THE SCENARIO MECHANICS, KICK-OFF, AND A SUB-TIMING CONFLICT",
    quality="community")

add_claim("THE LIMITED-TIME SCENARIO BLOCKS THE DAILY ONE, and there are only three attempts: 'they think we can score 4 goals in 45 minutes with half tired team with rare players... I tried 3 times and scoreline was 2*3, 3-3, 3-3. Your pass won't connect well your players forget to make some runs. **And the worst part you don't get normal scenario until limited time scenario is over or you use your all 3 chances.**' **So the 50-coin daily routine is NOT guaranteed - it can be taken away by an event, and the event can demand four goals in 45 minutes with a half-tired rare squad.**", 3, "scenarios/limited-time-blocks-the-daily", [e_sc], notes="The most operationally important scenario fact the corpus lacked")
add_claim("THE WIN-BY-N SCENARIO VARIANT: 'Recently, **they added an option to some scenarios where you would have to win with a 3 or 4 goals difference**, which made it a little more challenging yet still manageable. That was until I saw an extreme difficulty one yesterday: **Wolves vs Chelsea (play as) 2-2 at 57th minute. You have to win by a 4 goals difference.**' So a scenario can require four goals in the last 33 minutes - which is a genuine difficulty spike, not a routine.", 3, "scenarios/win-by-n-goals-variant", [e_sc])
add_claim("THE SCENARIO AI OBSERVATIONS, with two practical rules: 'Capable to do 3 sliding tackles in less than 1.5 second, the 3rd player will come pickup the loose ball... **AI can pickup ball despite being much further 5 meter away. Any pass above 40% power no matter how accurate, will get stolen.**' **So keep scenario passes under 40% power, and expect the AI to collect loose balls from further away than physics allows.**", 3, "scenarios/ai-loose-ball-and-pass-theft", [e_sc])
add_claim("THE SCENARIO EXPLOIT, from the other direction: 'i noticed scenarios are also way too easy in dls23 i literally never won a scenario now i easily win the very hard ones by 3-4 goals the thing is **AI defenders seem to have turned to shit and attackers take runs more frequently** if you just **pass around the halfway line to your wingers, it opens up so much space** and you can abuse that hence you can trick top tier teams with weaker players.' **So the exploitable shape is patient circulation at the halfway line to the wingers** - which is the same possession principle as the corpus's hold-the-ball rule, with a location attached.", 3, "scenarios/halfway-line-to-wingers-exploit", [e_sc])
add_claim("KICK-OFF IS THE MOST DANGEROUS MOMENT IN A MATCH: 'If they are C spammers, **hold possession most of the game, and play defensive as soon as they get the ball. Also, play defensive when they have kick-off. Kick-off is the most dangerous time.** If you take the ball during kick-off and hold possession for most of the game while slowly scoring goals, there you go - you beat them.' **So the one moment where the correct tactic changes before the ball is in motion is their kick-off.**", 3, "matchcraft/kickoff-is-the-most-dangerous-moment", [e_sc])
add_claim("THE KICK-OFF MAN-MARK: '**during the kickoff immediately run towards the player they want to target and man mark him with your forward while you hold down on the screen with your other finger so an ai player will press whoever they kicked off to.**' So the kick-off routine is: mark their target with your striker, and secondary-press the receiver - two fingers, two jobs, from the first second.", 3, "matchcraft/kickoff-man-mark", [e_sc])
add_claim("THE SET-PIECE ANTI-TURNOVER RULES: 'For set pieces, **always avoid turnovers. On goal kicks, loft pass to the defender on the opposite side of the goalie with almost full power by moving the arrow as far that direction as it can go. On free kicks, if the goalie is an option, take it. if not, do not shoot. Only legendary players can be trusted to hit that one in a million free kick goal.** Instead, pass to the closest and most open player. **On corner kicks, do not mess with the direction and kick it at 2/3 power.**' A conservative default that protects possession rather than chasing the low-percentage shot.", 3, "setpieces/anti-turnover-defaults", [e_sc])
add_claim("THE CROSS-FIELD LOFTED BALL CONFUSES THE AI: '**Cross field lofted balls also confuse the defensive ai**' - and 'most skill moves like a rainbow are high percentage and will get you a goal', with the standing caveat 'any tackle will make you lose the ball, so be smart and quick with passes.' So the switch of play is an AI-confusing tool as well as a space-creating one.", 3, "matchcraft/cross-field-lofted-ball-confuses-ai", [e_sc])
add_claim("A SUB-TIMING CONFLICT, OPENED AS C-031: the corpus's CLAIM-378 and CLAIM-1807 (both C2) say throw-ins and corners ALLOW substitutions. Two independent December 2024 reports say the opposite - '**You can't even make a substitution when the play is stopped for a throw-in, corner kick, etc.**' - and CLAIM-1125 records the same regression. **Recorded rather than silently preferring either claim: the general rule stands, but the regression is the more specific and later evidence, and it is not recorded as fixed.**", 3, "errata/c-031-sub-timing-conflict", [e_sc], notes="Opens C-031; device-verifiable in one match")
add_claim("THE CLAN RELEGATION ZONE: 'Only need 10 People I got 3 regulations... **The bottom 10 is the relegation zone. I always remove the bottom 10 but if any of them reach 100k they will never get removed. Avoid the bottom 10 at all cost to avoid potentially removed.**' **So a competitive clan runs a relegation zone with a 100k safety threshold** - the concrete form of the corpus's clan-choice-is-competitive finding, and a reason to check a clan's rules before joining.", 3, "clans/relegation-zone-management", [e_sc])
add_claim("THE SCREENSHOT-VERIFIED RECRUITMENT: 'Looking for **One more person willing to get a minimum of 50 wins** within the remaining time limit (5 days). **Send a screenshot of your prize ladder** & I'll DM you the code once you've met the conditions.' So elite clans verify claims with screenshots before issuing codes - which is what the recruitment market's 200k-350k expectations look like in practice.", 3, "clans/screenshot-verified-recruitment", [e_sc])
add_claim("THE CLAN-TAG REQUIREMENT AND DISCORD INTEGRATION: 'the first 5 players to join will get an **OG title role on the Discord server** and a direct say in clan announcements... **Willingness to represent the clan tag [AoG] in team name**' - and 'Be a member of an active clan if you don't want to join a clan just for the sake of it... **Preferably Division 1 or higher team**.' So competitive clans ask for a team-name tag, a Discord presence and a Division 1 squad.", 3, "clans/clan-tag-and-discord-requirements", [e_sc])
add_claim("THE RECORD RUN'S SELF-IMPOSED RULES, and the cleanest evidence that DLL alone is sufficient: '**No career mode matches, scenarios, dream draft, or any other game modes were allowed which could help upgrade my team and gain me gems and/or coins. I could ONLY play DLL matches and only use those rewards to upgrade my common team.**' So the 16-day, 145,296-XP record was achieved with one mode and one reward stream.", 3, "dll/record-run-dll-only-rules", [e_sc])
